// th16_s7_b1 -- TH16 v1.00a Extra final boss, first nonspell.
// Source: st07bs.ecl.txt Boss1:113-140 with dependency Boss1_at:193-216.
// Shell: validation.md independent invulnerable wrapper; source attack starts after OPENING_BUFFER.

const TIME_LIMIT: int = 3724;
const OPENING_BUFFER: int = 120;

// Boss1_at etSprite(0, 10, 4): source type 10, color 4 (bullet-types.md TH16_SHARD).
const TH16_SHARD: int = 512;
const SHARD_COLOR: int = 4;

// Boss1_at etSpeed(4.5, 3.0) over etCount(1, 5): v(q) = 4.5 - 0.375*q.
const LAYER_SPEED0: fx = 4.5fx;
const LAYER_SPEED_STEP: fx = -0.375fx;
// Boss1_at etDist(0, 32) then EX type 2 ANIM birth retreat position -= 4*velocity.
const BIRTH_DIST: fx = 32fx;
const ANIM_RETREAT: fx = 4fx;
// Boss1_at etOffset(0, 0, -24).
const EMIT_OFFSET_Y: fx = -24fx;

// moveRand(60, 4, 1.9) under entry moveLimit(0, 128, 280, 64).
const MOVE_FRAMES: int = 60;
const MOVE_SPEED0: fx = 1.9fx;
const LIMIT_X: fx = 140fx;   // limit width 280 centered at x=0
const LIMIT_Y_TOP: fx = 96fx;    // limit height 64 centered at y=128
const LIMIT_Y_BOTTOM: fx = 160fx;
const INNER_X: fx = 70fx;    // direction inner box = center +- width/4
const INNER_Y_TOP: fx = 112fx;   // center +- height/4
const INNER_Y_BOTTOM: fx = 144fx;

// Boss1_at: 100 bursts, one 1x5 wave every 3 frames, angle stepping +-8deg.
async sub boss1_at(step: angle) {
    var base: angle = aim_player();      // %B = %ANGLE_PLAYER
    for burst in 0..100 {                // $C = 100
        for q in 0..5 {                  // etCount(0, 1, 5)
            var v: fx = LAYER_SPEED0 + LAYER_SPEED_STEP * q;
            var net: fx = BIRTH_DIST - ANIM_RETREAT * v;
            _ = fire(TH16_SHARD, SHARD_COLOR,
                     $self_x + net * cos(base),
                     $self_y + EMIT_OFFSET_Y + net * sin(base),
                     v, base, none, none);
        }
        base = base + step;              // %B = %B + %A
        wait(3);                         // Boss1_at wait(3)
    }
}

// One source movement tick of moveRand: linear speed decay 1.9*(60-k)/60,
// fixed logical direction, then per-frame clamp to the entry moveLimit box.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < MOVE_FRAMES {
        var rem: fx = (MOVE_FRAMES - k) as fx;
        speed = MOVE_SPEED0 * rem / 60fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -LIMIT_X { nx = -LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_TOP { ny = LIMIT_Y_TOP; }
    if ny > LIMIT_Y_BOTTOM { ny = LIMIT_Y_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// moveRand(60, 4, 1.9): one signed direction sample per call, moveRand mode does
// not override the speed slot mode (linear). Inner box is center +- width/4, height/4.
sub begin_random_move() {
    var r: int = rand(65536) - 32768;    // signed unit random * pi, in BAM
    var a: int = r / 4;
    if $self_x < -INNER_X {
        a = r / 3;
    } else if $self_x > INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }  // source normalizes this branch
    } else {
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < INNER_Y_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > INNER_Y_BOTTOM {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad = 522 BAM around +-16384.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// Boss1: entry state from Boss:17/38/39 -> position (0,128), boxes 48/40 (r 24/20),
// body contact disabled by the inherited flag 0x2. Boss1:124 wait(60) precedes the loop.
async sub boss_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    wait(60);
    loop {
        spawn boss1_at(8deg);            // @Boss1_at(0.13962634f) async
        card_wait(100);                  // wait(100)
        begin_random_move();             // moveRand(60, 4, 1.9f)
        card_wait(60);                   // wait(60)
        spawn boss1_at(-8deg);           // @Boss1_at(-0.13962634f) async
        card_wait(100);
        begin_random_move();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
